    DEP_BANK bank;
    LogFile logFile;
    Attacker attacker;
    address victim = address(0xdead);
    uint constant VICTIM_DEPOSIT = 1 ether;
    uint constant ATTACKER_DEPOSIT = 1; // 1 wei

