        attacker.deposit{value: ATTACKER_DEPOSIT}();

        // After deposit, attacker contract balance should be 0
        assertEq(address(attacker).balance, 0);
    }

    function testReentrancyExploit() public {
        uint initialBankBalance = address(bank).balance;

        // Execute reentrancy attack
        attacker.attack(1); // Attack amount: 1 wei

        // Verify attacker gained extra wei
        assertEq(
            address(attacker).balance,
            2,
            "Attacker gained extra ETH illegally"
        );

        // Verify bank lost wei
        assertEq(
            address(bank).balance,
            initialBankBalance - 2,
            "Bank ETH balance not decreased correctly"
        );
    }
}

